const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const aoi = ee.Geometry.Point([-5.98, 37.38]).buffer(5000); // Seville, Spain
  const recentStartDate = '2023-03-25';
  const recentEndDate = '2023-04-23';
  const historicalStartYear = 2000;
  const historicalEndYear = 2010;

  // 2. Data Acquisition & Processing Functions
  // Sentinel-2 (for recent period)
  const getS2NDVI = (image) => {
    return image.normalizedDifference(['B8', 'B4']).rename('NDVI');
  };

  const maskS2Clouds = (image) => {
    const qa = image.select('QA60');
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0).and(
                   qa.bitwiseAnd(cirrusBitMask).eq(0));
    return image.updateMask(mask);
  };

  // Landsat 5/7 (for historical period)
  const getL5L7NDVI = (image) => {
    return image.normalizedDifference(['SR_B4', 'SR_B3']).rename('NDVI');
  };

  const maskL5L7Clouds = (image) => {
    const qa = image.select('QA_PIXEL');
    // See https://developers.google.com/earth-engine/datasets/catalog/LANDSAT_LT05_C02_T1_L2
    const cloudShadow = 1 << 4;
    const cloud = 1 << 5;
    const snow = 1 << 3;
    const mask = qa.bitwiseAnd(cloud).eq(0)
                   .and(qa.bitwiseAnd(cloudShadow).eq(0))
                   .and(qa.bitwiseAnd(snow).eq(0));
    return image.updateMask(mask);
  };

  // 3. Recent Period Analysis (2023)
  const s2Collection = ee.ImageCollection("COPERNICUS/S2_SR_HARMONIZED")
    .filterBounds(aoi)
    .filterDate(recentStartDate, recentEndDate)
    .map(maskS2Clouds);

  const s2_count = s2Collection.size().getInfo();
  if (s2_count === 0) {
    console.log("No Sentinel-2 images found for 2023.");
    console.log("C1");
    return;
  }

  const recentNDVI = s2Collection.map(getS2NDVI).mean();
  const recentStats = recentNDVI.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: aoi,
    scale: 1000,
    maxPixels: 1e9
  });

  const recentMean = recentStats.get('NDVI_mean').getInfo();
  const recentPixels = recentStats.get('NDVI_count').getInfo();

  if (recentPixels === 0) {
    console.log(`2023 Images: ${s2_count} (0 valid pixels after masking).`);
    console.log("C2");
    return;
  }
  console.log(`2023 NDVI: ${recentMean.toFixed(3)}, Images: ${s2_count}, Pixels: ${recentPixels}`);

  // 4. Historical Period Analysis (2000-2010)
  const l5 = ee.ImageCollection('LANDSAT/LT05/C02/T1_L2');
  const l7 = ee.ImageCollection('LANDSAT/LE07/C02/T1_L2');
  const landsatCollection = l5.merge(l7)
      .filterBounds(aoi)
      .filter(ee.Filter.calendarRange(historicalStartYear, historicalEndYear, 'year'))
      .filter(ee.Filter.calendarRange(3, 4, 'month')) // Broad filter for March/April
      .filter(ee.Filter.dayOfYear(ee.Date(recentStartDate).getRelative('day', 'year'), ee.Date(recentEndDate).getRelative('day', 'year')))
      .map(maskL5L7Clouds);

  const ls_count = landsatCollection.size().getInfo();
  if (ls_count === 0) {
    console.log("No Landsat images found for 2000-2010 period.");
    console.log("C1");
    return;
  }

  const historicalNDVI = landsatCollection.map(getL5L7NDVI).mean();
  const historicalStats = historicalNDVI.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: aoi,
    scale: 1000,
    maxPixels: 1e9
  });

  const historicalMean = historicalStats.get('NDVI_mean').getInfo();
  const historicalPixels = historicalStats.get('NDVI_count').getInfo();

  if (historicalPixels === 0) {
    console.log(`2000-2010 Images: ${ls_count} (0 valid pixels after masking).`);
    console.log("C2");
    return;
  }
  console.log(`2000-2010 NDVI: ${historicalMean.toFixed(3)}, Images: ${ls_count}, Pixels: ${historicalPixels}`);

  // 5. Validation & Final Answer
  if (recentMean === null || historicalMean === null) {
    console.log("Calculation failed, result is null.");
    console.log("C3");
    return;
  }

  console.log(`Comparison: 2023 NDVI (${recentMean.toFixed(3)}) vs Hist. NDVI (${historicalMean.toFixed(3)})`);

  if (recentMean > historicalMean) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(err => {
    console.error("An error occurred:", err);
    console.log("D");
});
